#!/usr/bin/env python3
import argparse, csv, json, os, pwd, grp, stat, sys, time, re
from datetime import datetime, timezone
from pathlib import Path
import filter_utils
from permissions import format_permissions
from plugins_cmd import run as plugin_run
from csv_utils import csv_output
from sort_utils import sort_records
from theme_cmd import run as theme_run

def meta(p):
    try:
        st=os.lstat(p); mode=st.st_mode
        typ='symlink' if stat.S_ISLNK(mode) else ('dir' if stat.S_ISDIR(mode) else 'file')
        try: user=pwd.getpwuid(st.st_uid).pw_name
        except Exception: user=str(st.st_uid)
        try: group=grp.getgrgid(st.st_gid).gr_name
        except Exception: group=str(st.st_gid)
        try: target=os.readlink(p) if typ=='symlink' else None
        except Exception: target=None
        def iso(t): return datetime.fromtimestamp(t,timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        name=os.path.basename(os.path.normpath(p)) or p
        ext=os.path.splitext(name)[1][1:] or None
        return {'path':os.path.abspath(p),'name':name,'extension':ext,'file_type':typ,'size_bytes':st.st_size,'modified':iso(st.st_mtime),'created':iso(getattr(st,'st_birthtime',st.st_ctime)),'accessed':iso(st.st_atime),'mode_octal':format(stat.S_IMODE(mode),'04o'),'owner_user':user,'owner_group':group,'inode':st.st_ino,'hard_links':st.st_nlink,'symlink_target':target,'is_hidden':name.startswith('.'),'git_status':None,'plugin':{}}
    except OSError: return None

def parse_args():
    p=argparse.ArgumentParser(prog='lla',add_help=True)
    p.add_argument('directory',nargs='?',default='.'); p.add_argument('-V','--version',action='version',version='lla 0.5.7'); p.add_argument('-a','--all',action='store_true'); p.add_argument('-A','--almost-all',action='store_true')
    p.add_argument('-c','--case-sensitive',action='store_true'); p.add_argument('--created'); p.add_argument('--csv',action='store_true'); p.add_argument('-d','--depth',type=int,default=1); p.add_argument('--dirs-only',action='store_true'); p.add_argument('--dotfiles-only',action='store_true'); p.add_argument('-f','--filter'); p.add_argument('--files-only',action='store_true'); p.add_argument('-g','--grid',action='store_true'); p.add_argument('--grid-ignore',action='store_true'); p.add_argument('-G','--git',action='store_true'); p.add_argument('--hide-group',action='store_true'); p.add_argument('--include-dirs',action='store_true'); p.add_argument('--json',action='store_true'); p.add_argument('-l','--long',action='store_true'); p.add_argument('--modified'); p.add_argument('--ndjson',action='store_true'); p.add_argument('--no-color',action='store_true'); p.add_argument('--no-dirs',action='store_true'); p.add_argument('--no-dotfiles',action='store_true'); p.add_argument('--no-files',action='store_true'); p.add_argument('--no-symlinks',action='store_true'); p.add_argument('--permission-format',default='symbolic'); p.add_argument('--pretty',action='store_true'); p.add_argument('-r','--sort-reverse',action='store_true'); p.add_argument('-R','--recursive',action='store_true'); p.add_argument('-s','--sort',choices=['name','size','date'],default='name'); p.add_argument('--size'); p.add_argument('--sort-case-sensitive',action='store_true'); p.add_argument('--sort-dirs-first',action='store_true'); p.add_argument('--sort-natural',action='store_true'); p.add_argument('--symlinks-only',action='store_true'); p.add_argument('-t','--tree',action='store_true'); p.add_argument('-T','--table',action='store_true'); p.add_argument('--timeline',action='store_true'); p.add_argument('-S','--sizemap',action='store_true'); p.add_argument('--search'); p.add_argument('--search-context',type=int,default=2); p.add_argument('--respect-gitignore',action='store_true'); p.add_argument('--no-gitignore',action='store_true')
    return p.parse_args()

def main():
    if len(sys.argv)>1 and sys.argv[1]=='theme':
      result=theme_run(sys.argv[1:])
      if result is not None: return result
    if len(sys.argv)>1 and plugin_run(sys.argv[1:]): return 0
    a=parse_args(); root=os.path.abspath(a.directory)
    if not os.path.exists(root): print(f"\n✗ Error\n\n  Path '{a.directory}' does not exist or is not accessible\n",file=sys.stderr); return 1
    paths=[]
    if os.path.isfile(root) or os.path.islink(root): paths=[a.directory]
    else:
      def walk(d,level):
        try: entries=sorted(os.scandir(d),key=lambda e:e.name.casefold())
        except OSError: return
        for e in entries:
          if e.name in ('.','..'): continue
          if not (a.all or a.almost_all) and a.no_dotfiles and e.name.startswith('.'): continue
          ep=os.path.join(d,e.name); paths.append(ep)
          try: isdir=e.is_dir(follow_symlinks=False)
          except OSError: isdir=False
          if isdir and (a.recursive or a.tree) and level < max(1,a.depth if a.depth else 999999): walk(ep,level+1)
      walk(a.directory,1)
    rows=[]
    for path in paths:
      x=meta(path)
      if not x: continue
      typ=x['file_type']; n=x['name']
      if a.no_dotfiles and n.startswith('.'): continue
      if a.dotfiles_only and not n.startswith('.'): continue
      if a.dirs_only and typ!='dir' or a.files_only and typ!='file' or a.symlinks_only and typ!='symlink': continue
      if a.no_dirs and typ=='dir' or a.no_files and typ=='file' or a.no_symlinks and typ=='symlink': continue
      if a.filter and not filter_utils.name_matches(n,a.filter,a.case_sensitive): continue
      if a.size and not filter_utils.size_matches(x['size_bytes'],a.size): continue
      if a.modified:
        ts=datetime.fromisoformat(x['modified'].replace('Z','+00:00')).timestamp()
        if not filter_utils.time_matches(ts,a.modified): continue
      if a.created:
        ts=datetime.fromisoformat(x['created'].replace('Z','+00:00')).timestamp()
        if not filter_utils.time_matches(ts,a.created): continue
      if a.search and typ=='file':
        try:
          content=Path(path).read_text(errors='ignore'); pattern=a.search
          matched=(pattern[6:] in content if pattern.startswith('regex:') else pattern in content)
          if not matched: continue
        except Exception: continue
      rows.append(x)
    rows=sort_records(rows,criterion=a.sort,reverse=a.sort_reverse,dirs_first=a.sort_dirs_first,
                      case_sensitive=a.sort_case_sensitive,natural=a.sort_natural or a.sort=='name')
    if a.json:
      print(json.dumps(rows,indent=2 if a.pretty else None,
                       separators=None if a.pretty else (',', ':'),ensure_ascii=False)); return 0
    if a.ndjson:
      for x in rows: print(json.dumps(x,separators=(',',':'),ensure_ascii=False))
      return 0
    if a.csv:
      print(csv_output(rows))
      return 0
    if a.long:
      for x in rows:
        try: mode=format_permissions(os.stat(x['path'],follow_symlinks=False).st_mode,a.permission_format)
        except Exception: mode=x['mode_octal']
        size=f"{x['size_bytes']}B"; suffix='/' if x['file_type']=='dir' else ''
        date=datetime.fromisoformat(x['modified'].replace('Z','+00:00')).strftime('%b %d %H:%M')
        g='' if a.hide_group else f" {x['owner_group']}"
        link = f" -> {x['symlink_target']}" if x['file_type']=='symlink' and x['symlink_target'] else ''
        print(f"{mode} {size:>4} {date} {x['owner_user']}{g} {x['name']}{suffix}{link}")
      return 0
    for x in rows: print(x['name']+('/' if x['file_type']=='dir' else ''))
    return 0
if __name__=='__main__':
    try: sys.exit(main())
    except BrokenPipeError: pass

